<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_super_admin();$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT * FROM users WHERE id=?');$st->execute([$id]);$u=$st->fetch();if(!$u)exit('User not found');$locs=db()->query('SELECT id,code,name FROM locations WHERE active=1 ORDER BY code')->fetchAll();$st=db()->prepare('SELECT location_id FROM user_locations WHERE user_id=?');$st->execute([$id]);$assigned=array_map('intval',array_column($st->fetchAll(),'location_id'));$err='';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$password=$_POST['password']??'';try{if($name==='')throw new Exception('Name required.');db()->beginTransaction();if($u['role']==='super_admin'){$st=db()->prepare('UPDATE users SET name=? WHERE id=?');$st->execute([$name,$id]);}else{$role=$_POST['role']??$u['role'];$allowed=['manager','cashier','godown','auditor'];if(!in_array($role,$allowed,true))throw new Exception('Invalid role.');$chosen=array_values(array_unique(array_filter(array_map('intval',$_POST['locations']??[]))));if(!$chosen)throw new Exception('Assign at least one location.');$active=isset($_POST['active'])?1:0;license_require_reactivation_capacity($id,(bool)$active);$st=db()->prepare('UPDATE users SET name=?,role=?,active=? WHERE id=?');$st->execute([$name,$role,$active,$id]);db()->prepare('DELETE FROM user_locations WHERE user_id=?')->execute([$id]);$ins=db()->prepare('INSERT INTO user_locations(user_id,location_id) VALUES(?,?)');foreach($chosen as $lid)$ins->execute([$id,$lid]);}
 if($password!==''){if(strlen($password)<10)throw new Exception('New password must be 10+ characters.');db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$id]);}
 db()->prepare('UPDATE users SET auth_version=auth_version+1 WHERE id=?')->execute([$id]);
 db()->commit();audit('USER_UPDATE','user',$id,['password_reset'=>$password!==''?1:0]);$msg='User updated.';$st=db()->prepare('SELECT * FROM users WHERE id=?');$st->execute([$id]);$u=$st->fetch();$st=db()->prepare('SELECT location_id FROM user_locations WHERE user_id=?');$st->execute([$id]);$assigned=array_map('intval',array_column($st->fetchAll(),'location_id'));
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}}
page_header('Edit User / Reset Password');if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>'; ?>
<form method="post" class="panel"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row"><div><label>Name</label><input name="name" value="<?=e($u['name'])?>" required></div><div><label>Username</label><input value="<?=e($u['username'])?>" readonly></div></div><br><?php if($u['role']!=='super_admin'):?><div class="row"><div><label>Role</label><select name="role"><?php foreach(['cashier','godown','manager','auditor'] as $r):?><option value="<?=$r?>" <?=$u['role']===$r?'selected':''?>><?=ucfirst($r)?></option><?php endforeach;?></select><br><br><label><input type="checkbox" name="active" value="1" style="width:auto" <?=$u['active']?'checked':''?>> Active</label></div><div><label>Assigned Locations</label><select name="locations[]" multiple size="6"><?php foreach($locs as $l):?><option value="<?=$l['id']?>" <?=in_array((int)$l['id'],$assigned,true)?'selected':''?>><?=e($l['code'].' · '.$l['name'])?></option><?php endforeach;?></select></div></div><br><?php else:?><div class="notice">Super Admin role cannot be deactivated or downgraded from this screen.</div><?php endif;?><label>New Password (leave blank to keep current)</label><input type="password" name="password" minlength="10"><br><br><button class="btn">Save User</button></form><?php page_footer();
